import numpy as np
def equation(t, x, v, params):
    w = 0.4067
    c = np.cos(w*t); s = np.sin(w*t)
    return (params[0] + params[1]*x + params[2]*v + params[3]*np.sin(v) + params[4]*v*np.abs(v)
            + params[5]*c + params[6]*s + params[7]*c*x + params[8]*c*v + params[9]*np.sqrt(x))
